"""Exchange rates from the remote rates API, over httpx."""
import certifi
import httpx

TIMEOUT = httpx.Timeout(5.0, connect=2.0)


def rates_client(transport=None, proxy_url=None):
    """The legacy rates mirror is only reachable through the corporate proxy."""
    proxies = {"all://legacy-rates.internal": proxy_url} if proxy_url else None
    return httpx.Client(
        base_url="https://rates.example.test",
        timeout=TIMEOUT,
        verify=certifi.where(),
        proxies=proxies,
        transport=transport,
        headers={"User-Agent": "pricing-gateway/2.1"},
    )


def latest(client, base, symbols):
    resp = client.get("/latest", params={"base": base, "symbols": ",".join(symbols)})
    resp.raise_for_status()
    return resp.json()["rates"]


def convert(client, cents, currency):
    rate = latest(client, "USD", [currency])[currency]
    return round(cents * rate / 100, 2)


def lookup_error(client, base):
    try:
        latest(client, base, ["EUR"])
    except httpx.HTTPStatusError as exc:
        return exc.response.status_code, exc.response.json()["error"]
    return None

