"""Pricing service: a plain ASGI app (the gateway and the tests call it in-process)."""
import json

PRICES = {"apple": 120, "pear": 95, "fig": 310}


def route(method, path):
    if path == "/health":
        return 200, {"ok": True}
    if path == "/prices" and method == "GET":
        return 200, {"items": sorted(PRICES)}
    if path.startswith("/price/"):
        name = path.rsplit("/", 1)[-1]
        if name in PRICES:
            return 200, {"item": name, "cents": PRICES[name]}
        return 404, {"error": "unknown item"}
    return 404, {"error": "no route"}


async def app(scope, receive, send):
    assert scope["type"] == "http"
    status, payload = route(scope["method"], scope["path"])
    body = json.dumps(payload).encode()
    await send({"type": "http.response.start", "status": status,
                "headers": [(b"content-type", b"application/json"),
                            (b"content-length", str(len(body)).encode())]})
    await send({"type": "http.response.body", "body": body})

