import json

import httpx

from app import rates

RATES = {"EUR": 0.9, "GBP": 0.8, "JPY": 150.0}


def _json(status, payload):
    return httpx.Response(status, content=json.dumps(payload).encode(),
                          headers={"Content-Type": "application/json"})


def handler(request):
    if request.url.path != "/latest":
        return _json(404, {"error": "no route"})
    base = request.url.params["base"]
    if base != "USD":
        return _json(422, {"error": f"unsupported base {base}"})
    wanted = request.url.params["symbols"].split(",")
    return _json(200, {"base": base, "rates": {s: RATES[s] for s in wanted}})


def client():
    return rates.rates_client(transport=httpx.MockTransport(handler),
                              proxy_url="http://proxy.internal:3128")


def test_latest():
    with client() as c:
        assert rates.latest(c, "USD", ["EUR", "GBP"]) == {"EUR": 0.9, "GBP": 0.8}


def test_convert():
    with client() as c:
        assert rates.convert(c, 1999, "JPY") == 2998.5


def test_lookup_error():
    with client() as c:
        assert rates.lookup_error(c, "CHF") == (422, "unsupported base CHF")
        assert rates.lookup_error(c, "USD") is None


def test_client_defaults():
    with rates.rates_client() as c:
        assert str(c.base_url) == "https://rates.example.test"
        assert c.headers["User-Agent"] == "pricing-gateway/2.1"
        assert c.timeout.connect == 2.0 and c.timeout.read == 5.0
